"""Owner-only real-race manual 3連単 formation notebook.

No licensed records or prediction engine. JS only stores manual drafts in
same-origin localStorage; WSGI only serves fixed source text after authentication.
"""
HTML = "<!doctype html><html lang=\"ja\"><head><meta charset=\"utf-8\"><meta name=\"viewport\" content=\"width=device-width,initial-scale=1\"><title>競馬ナイン｜自分の3連単下書き</title><meta name=\"keiba-owner-release\" content=\"__OWNER_RELEASE__\"><meta name=\"theme-color\" content=\"#09172b\"><meta name=\"apple-mobile-web-app-capable\" content=\"yes\"><meta name=\"apple-mobile-web-app-status-bar-style\" content=\"default\"><meta name=\"apple-mobile-web-app-title\" content=\"競馬ナイン本人用\"><link rel=\"stylesheet\" href=\"/my-tickets.css\"></head><body><main><header><a href=\"/\" class=\"back\">← 本人用ホーム</a><a href=\"https://esakahumihumi1125-byte.github.io/keiba-nine/\" class=\"back app-home-link\">🏇 いつもの競馬ナインへ</a><h1>自分の3連単下書き</h1><p class=\"muted\">実際の開催日を選べる、本人用の手動フォーメーション作成帳。</p><p class=\"warning\">これは本人が選んだ買い目の下書きです。AI予想・JRAの出走確定・購入履歴ではありません。</p><nav class=\"owner-shortcuts\" aria-label=\"本人用のページ内メニュー\"><a href=\"#racePicker\">レース選択</a><a href=\"#formationPanel\">3連単を作る</a><a href=\"#bulkPanel\">全Rまとめ登録</a><a href=\"#savedPanel\">保存済み</a><a href=\"#actualPurchasePanel\">購入記録</a></nav><p class=\"muted\">ホーム画面から開いたアプリとSafariは保存領域が異なる場合があります。実戦記録はJSONバックアップを残してください。</p><details class=\"release-details\"><summary>今の配信版を確認する</summary><p>この画面の配信識別子：<code>__OWNER_RELEASE__</code></p><p>GitHubの更新後も古い表示なら、本人用ホームの「配信中の版を照合」から確認してな。編集途中の3連単は、保存してから更新してな。</p></details></header><section id=\"racePicker\"><h2>開催日・レースを選択</h2><div class=\"weekend-jump\"><button id=\"mSaturday\" type=\"button\" class=\"secondary\">今週の土曜</button><button id=\"mSunday\" type=\"button\" class=\"secondary\">今週の日曜</button></div><label for=\"mDate\">日付</label><input id=\"mDate\" type=\"date\"><div class=\"day-coverage\"><strong>選択日の全場・全R準備状況（この端末内）</strong><p id=\"mDayCoverageSummary\" class=\"muted\">日付を選ぶと、取り込み済みの開催と下書きを確認できます。</p><div id=\"mDayCoverage\" class=\"day-coverage-grid\" role=\"group\" aria-label=\"選択日の端末内保存状況・競馬場を選択\"></div><p class=\"muted\">表示するのは取り込み済みのJRDB想定メール・本人転記の馬番メモ・下書きだけ。JRAの開催、出走確定、AI予想ではありません。</p></div><div class=\"two\"><div><label for=\"mTrack\">競馬場</label><select id=\"mTrack\"><option value=\"\">競馬場を選択</option><option value=\"札幌\">札幌</option><option value=\"函館\">函館</option><option value=\"福島\">福島</option><option value=\"新潟\">新潟</option><option value=\"東京\">東京</option><option value=\"中山\">中山</option><option value=\"中京\">中京</option><option value=\"京都\">京都</option><option value=\"阪神\">阪神</option><option value=\"小倉\">小倉</option></select></div><div><label for=\"mRace\">レース</label><select id=\"mRace\"><option value=\"1\">1R</option><option value=\"2\">2R</option><option value=\"3\">3R</option><option value=\"4\">4R</option><option value=\"5\">5R</option><option value=\"6\">6R</option><option value=\"7\">7R</option><option value=\"8\">8R</option><option value=\"9\">9R</option><option value=\"10\">10R</option><option value=\"11\">11R</option><option value=\"12\">12R</option></select></div></div><div class=\"race-nav\"><button id=\"mPrevRace\" type=\"button\" class=\"secondary\">← 前のR</button><button id=\"mNextRace\" type=\"button\" class=\"secondary\">次のR →</button></div><div class=\"race-board\"><strong>選択した競馬場の1R〜12R</strong><p id=\"mRaceBoardStatus\" class=\"muted\">競馬場を選ぶと、保存済みの下書きを確認できます。</p><div id=\"mRaceBoard\" class=\"race-board-grid\" role=\"group\" aria-label=\"1Rから12Rの下書き選択\"></div><p class=\"muted\">保存状況の一覧です。開催有無・出走馬・取消を自動確認したものではありません。</p></div><details class=\"roster-box\"><summary>このレースの馬番・馬名メモ（本人転記）</summary><p id=\"mRosterStatus\" class=\"muted\">開催日・競馬場・Rを選ぶと表示します。</p><div id=\"mRosterRows\"></div><p class=\"muted\">JRA公式の自動照合ではありません。出走取消・馬場・発走時刻は別途確認してください。</p><a href=\"/jrdb-mail-local\">馬番メモの照合画面へ</a></details></section><section id=\"formationPanel\"><h2>3連単フォーメーション</h2><p class=\"muted\">1着・2着・3着に入れる馬番をタップ。各着順は複数選択OK。重複を除いて最大48点。</p><details class=\"paste-box\"><summary>ChatGPTの3連単をまとめて貼る</summary><p class=\"muted\">予想の1着・2着・3着を3行コピーして貼るだけ。丸数字①〜⑱にも対応。現在の選択へ反映するだけで、保存・購入はしません。</p><label for=\"mPaste\">フォーメーションを貼り付け</label><textarea id=\"mPaste\" rows=\"4\" maxlength=\"1200\" placeholder=\"1着：①②&#10;2着：①②③④&#10;3着：①②③④⑤⑥⑦⑧\"></textarea><button id=\"mApplyPaste\" type=\"button\" class=\"secondary\">貼り付けた3連単を反映</button><p class=\"muted\">日付・競馬場・Rを先に選択。48点以内だけ反映。購入記録には登録されません。</p></details><details class=\"rank-helper\"><summary>S・A・Bの手入力評価から3連単を組む</summary><p class=\"muted\">本人が入力した馬番だけを使った<b>買い目編成の補助</b>です。AI予想・調教分析・JRA公式照合ではありません。Sは最大2頭、A・Bは評価の高い順に入力してな。</p><div class=\"rank-fields\"><label for=\"mRankS\" class=\"rank-s\">Sランク（1〜2頭）</label><input id=\"mRankS\" type=\"text\" maxlength=\"80\" autocomplete=\"off\" placeholder=\"①②\"><label for=\"mRankA\" class=\"rank-a\">Aランク（1頭以上）</label><input id=\"mRankA\" type=\"text\" maxlength=\"80\" autocomplete=\"off\" placeholder=\"③④⑤\"><label for=\"mRankB\" class=\"rank-b\">Bランク（任意）</label><input id=\"mRankB\" type=\"text\" maxlength=\"80\" autocomplete=\"off\" placeholder=\"⑥⑦⑧⑨\"></div><button id=\"mRankBuild\" type=\"button\" class=\"secondary\">30〜40点を目安に組み立てる</button><p id=\"mRankStatus\" role=\"status\" class=\"muted\">作成しても保存・購入はしません。組み合わせを確認してください。</p></details><h3>1着候補</h3><div id=\"mFirst\" class=\"numbers\" aria-label=\"1着候補\"></div><p id=\"mFirstNames\" class=\"selected-names\" aria-live=\"polite\"></p><h3>2着候補</h3><div id=\"mSecond\" class=\"numbers\" aria-label=\"2着候補\"></div><p id=\"mSecondNames\" class=\"selected-names\" aria-live=\"polite\"></p><h3>3着候補</h3><div id=\"mThird\" class=\"numbers\" aria-label=\"3着候補\"></div><p id=\"mThirdNames\" class=\"selected-names\" aria-live=\"polite\"></p><p id=\"mNumberReview\" class=\"number-review\" role=\"status\"></p><p class=\"muted\">作り方：通常は着順別に馬番を選択。軸流しは、選んだ候補から3着や2着を自動でセットします（保存前に全買い目を確認）。</p><div class=\"quick-actions\"><button id=\"mAxisSingle\" type=\"button\" class=\"secondary\">1頭軸ながし（1着固定）</button><button id=\"mAxisPair\" type=\"button\" class=\"secondary\">2頭軸ながし（1・2着）</button><button id=\"mCopyThird\" type=\"button\" class=\"secondary\">2着候補を3着にもコピー</button></div><div class=\"total\"><div>買い目<strong id=\"mCount\">0点</strong></div><div>1点100円<strong id=\"mCost\">0円</strong></div></div><p id=\"mMsg\" role=\"status\" class=\"muted\">各着順の馬番を選択してください。</p><button id=\"mSave\" disabled>このレースの下書きを保存</button><button id=\"mReset\" class=\"secondary\">選択をクリア</button><details><summary>作成した全買い目を見る</summary><ol id=\"mTickets\"></ol></details></section><section id=\"bulkPanel\"><h2>全Rの3連単下書きをまとめて貼る</h2><p class=\"muted\">ChatGPTで作った複数レースの3連単フォーメーションを一度に検査して、本人の確認後に下書き保存します。JRA公式照合・AI自動予想・馬券購入ではありません。</p><details class=\"bulk-box\"><summary>複数レースをまとめて入力（最大36R）</summary><p class=\"muted\">4行で1レース。各レースの日付・競馬場・Rを必ず書いてください。空行は自由です。すべて48点以内でないと保存しません。</p><textarea id=\"mBulkPaste\" rows=\"10\" maxlength=\"25000\" placeholder=\"2026-11-07 東京1R&#10;1着：①②&#10;2着：①②③④&#10;3着：①②③④⑤⑥⑦⑧&#10;&#10;2026-11-07 京都1R&#10;1着：①&#10;2着：②③&#10;3着：②③④\"></textarea><button id=\"mBulkReview\" type=\"button\" class=\"secondary\">全レースの点数を検査する</button><p id=\"mBulkStatus\" class=\"muted\" role=\"status\">検査しても保存しません。内容を確認後、保存を選んでください。</p><div id=\"mBulkPreview\" role=\"region\" aria-label=\"複数レースの下書き検査結果\"></div><button id=\"mBulkApply\" type=\"button\" disabled>確認した下書きを一括保存</button><p class=\"muted\">同じ日付・競馬場・Rの保存済み下書きは確認後に上書きします。実購入記録・払戻・JRDBメールメモ・Googleシートには反映されません。取消馬や馬番の最新状況は本人が別途確認してください。</p></details></section><section id=\"savedPanel\"><h2>選択した日付の保存済み下書き</h2><p class=\"muted\">他の日付の買い目はこの画面には表示しません。日付を変えると、その日の下書きを確認できます。</p><p id=\"mDaySummary\" class=\"day-summary\" role=\"status\"></p><div id=\"mSaved\" role=\"region\" aria-label=\"保存済み下書き\"></div><label for=\"mImport\">JSONバックアップから下書きを復元</label><input id=\"mImport\" type=\"file\" accept=\".json,application/json\"><p class=\"muted\">事前に現在の下書きを書き出してください。復元時は内容確認後、現在の下書き全件と入れ替えます。ファイルはサーバーへ送信されません。</p><button id=\"mExport\" class=\"secondary\">下書きをJSONでバックアップ</button><p class=\"muted\">このブラウザの端末内だけに保存（Google同期なし）。プライベートブラウズ・ChatGPT内ブラウザ・Safariは保存領域が異なる場合があります。端末変更やサイトデータ削除に備え、Safariからバックアップしてください。</p></section></main><script src=\"/my-tickets.js\" defer></script></body></html>"
CSS = "*{box-sizing:border-box}html{color-scheme:dark}body{margin:0;background:#09172b;color:#f1f6ff;font:16px/1.55 system-ui,sans-serif}main{max-width:640px;margin:auto;padding:18px 14px 40px}a{color:#edca70}h1{font-size:26px;margin:10px 0}h2{font-size:20px;margin:0 0 10px}h3{font-size:16px;margin:17px 0 7px}.back{font-size:14px}.app-home-link{display:inline-block;margin:5px 0 0 14px}section{background:#172d48;border:1px solid #385471;border-radius:16px;padding:18px;margin:16px 0}.muted{font-size:13px;color:#c8d7e6}.warning{background:#312b23;border:1px solid #a8884c;border-radius:12px;padding:12px;color:#ffe2a0;font-size:13px}label{display:block;margin:8px 0 5px;font-weight:700}input,select{width:100%;border:1px solid #7992aa;border-radius:10px;background:#0d243c;color:#fff;min-height:48px;padding:10px;font:inherit}.two{display:grid;grid-template-columns:1fr 1fr;gap:10px}.race-nav,.quick-actions{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:8px;margin:10px 0 6px}.day-coverage{background:#102741;border:1px solid #4d6581;padding:12px;border-radius:12px;margin:14px 0}.day-coverage>strong{display:block;font-size:15px;color:#edca70}.day-coverage-grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(135px,1fr));gap:8px}.day-coverage-grid button{margin:0;min-height:70px;padding:10px 7px;text-align:left;font-size:14px;background:#2c4665;color:#f7f8ff;border:1px solid #627c9b}.day-coverage-grid button.active-track{border-color:#f2ca70}.day-coverage-grid small{display:block;font-size:12px;color:#d5e3f0;line-height:1.5;margin-top:3px}.weekend-jump{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:8px;margin:7px 0}.weekend-jump button{margin:0;min-height:44px;font-size:14px}.race-board-grid button.has-provisional:not(.has-draft){background:#294260}.race-board-grid button.has-manual:not(.has-draft){border-color:#9ec7a9}.race-nav button,.quick-actions button{margin:0;min-height:46px;font-size:14px}.owner-update-notice{position:sticky;top:0;z-index:30;background:#312b23;border:2px solid #dcbf73;color:#ffedb4;padding:12px;border-radius:0 0 12px 12px;font-size:14px}.owner-update-notice p{margin:0 0 6px}.owner-update-notice button{display:inline-block;width:auto;min-height:44px;padding:9px 16px}.release-details{border:1px solid #45627f;border-radius:9px;padding:8px 11px;margin:8px 0 14px;font-size:12px;color:#bcd0e4}.release-details summary{cursor:pointer;font-weight:700;color:#edd083}.release-details p{overflow-wrap:anywhere;margin:8px 0}.release-details code{color:#f0e4ba}.owner-shortcuts{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:8px;margin:14px 0}.owner-shortcuts a{display:flex;align-items:center;justify-content:center;text-align:center;text-decoration:none;font-weight:700;font-size:14px;min-height:48px;border:1px solid #7b95ae;background:#263f5e;border-radius:10px;color:#ffe0a0;padding:10px}.owner-shortcuts a:last-child{grid-column:1/-1}.owner-shortcuts a:focus-visible{outline:3px solid #ffd76d;outline-offset:2px}section[id]{scroll-margin-top:14px}.race-board{margin:13px 0;padding:12px;border:1px solid #4d6581;border-radius:12px;background:#102741}.race-board>strong{display:block;font-size:15px;color:#edca70}.race-board-grid{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:8px;margin:10px 0}.race-board-grid button{display:block;margin:0;min-width:0;min-height:56px;padding:8px 4px;font-size:14px;line-height:1.3;background:#2a4059;color:#f0f4fa;border:2px solid #475d76}.race-board-grid button.has-draft{background:#314e53;color:#f2e2a0;border-color:#859771}.race-board-grid button.active-race{border-color:#ffd76d;box-shadow:0 0 0 1px #ffd76d}.race-board-grid button small{display:block;font-size:11px;font-weight:500;margin-top:3px;color:inherit;opacity:.9}@media(max-width:360px){.race-board-grid{gap:5px}.race-board-grid button{min-height:52px;font-size:13px;padding:5px 2px}}.quick-actions button:last-child{grid-column:1/-1}.quick-actions button:disabled{opacity:.36}.numbers{display:grid;grid-template-columns:repeat(6,minmax(0,1fr));gap:7px}.num{border:1px solid #617996;background:#0a2239;color:#fff;border-radius:8px;min-height:48px;padding:0;font:700 18px system-ui}.num.selected{background:#d4af37;border-color:#f3d17a;color:#10213b}.total{display:grid;grid-template-columns:1fr 1fr;gap:8px;margin-top:22px}.total>div{background:#0c2239;padding:12px 8px;border-radius:11px;text-align:center;font-size:12px;color:#cfdded}.total strong{display:block;font-size:26px;color:#fff;font-variant-numeric:tabular-nums}button{font:700 16px system-ui;min-height:49px;padding:10px 15px;border:0;border-radius:10px;background:#edca70;color:#11243b;margin:8px 0;cursor:pointer}button:disabled{opacity:.45;cursor:not-allowed}button.secondary{background:#304d6e;color:#fff}#mSave{width:100%}#mReset,#mExport{width:100%}details{border:1px solid #4d6581;border-radius:10px;padding:12px;margin-top:14px}details summary{cursor:pointer}ol{columns:2;font-size:14px;line-height:1.9}textarea{display:block;width:100%;min-height:126px;resize:vertical;background:#0d243c;color:#fff;border:1px solid #7992aa;border-radius:10px;padding:10px;font:inherit;line-height:1.55}textarea::placeholder{color:#abbdd0}.paste-box{margin:13px 0}.paste-box #mApplyPaste{width:100%}.saved{padding:13px 0;border-bottom:1px solid #3d5874}.day-summary{background:#0c2239;border:1px solid #3e5f80;color:#edca70;border-radius:10px;padding:12px;font-weight:700;font-size:14px}.saved strong{display:block}.saved .secondary{min-height:40px;margin-right:8px}.roster-box{margin-top:14px;padding:12px;border:1px solid #527092;border-radius:12px}.roster-box summary{cursor:pointer;font-weight:700;color:#edca70}.roster-row{margin:5px 0;padding:5px 8px;border-bottom:1px solid #385471;font-size:15px}.selected-names{margin:7px 0 13px;font-size:13px;color:#d9e4f3;padding:8px 10px;background:#112943;border-radius:8px;overflow-wrap:anywhere}.selected-names:empty{display:none}.number-review{margin:10px 0 15px;padding:11px 12px;border:1px solid #637f9f;border-radius:10px;background:#102e48;color:#ddeaf3;font-size:13px;line-height:1.6}.number-review.needs-check{border-color:#c69d57;background:#352c21;color:#ffecbb}.number-review:empty{display:none}.bulk-box #mBulkReview,.bulk-box #mBulkApply{width:100%}.bulk-review-card{margin:8px 0;padding:10px;border:1px solid #527092;border-radius:10px}.rank-helper{border:1px solid #627e9a;padding:12px;border-radius:12px;margin:14px 0}.rank-helper summary{font-weight:800;color:#f3d17e;cursor:pointer}.rank-fields{display:grid;grid-template-columns:1fr;gap:4px}.rank-fields input{min-height:46px}.rank-s{color:#f2d080}.rank-a{color:#ff958f}.rank-b{color:#c6d6e6}.rank-helper button{min-height:48px;width:100%;margin-top:12px}.bulk-review-card summary{font-size:14px;font-weight:700;color:#edca70}.bulk-review-card p{font-size:13px;line-height:1.7;margin:8px 0}.bulk-review-tickets{overflow-wrap:anywhere;color:#d8e5f3}p{overflow-wrap:anywhere}@media(max-width:360px){.numbers{gap:5px}.num{min-height:44px;font-size:16px}section{padding:13px}}"
JS = "'use strict';\n// Private, browser-only operator draft. No licensed data, official prediction,\n// purchased-ticket claim, provider API call or server-side persistence.\nconst $=id=>document.getElementById(id);\nconst KEY='keiba-nine-owner-ticket-drafts-v1', LIMIT=48, MAX_SAVED=300;\nconst TRACKS=[\"札幌\",\"函館\",\"福島\",\"新潟\",\"東京\",\"中山\",\"中京\",\"京都\",\"阪神\",\"小倉\"];\nconst sorted=s=>[...s].sort((a,b)=>a-b);\nfunction ticketsFor(first,second,third){\n const tickets=[],unique=new Set();\n for(const a of sorted(first))for(const b of sorted(second))for(const c of sorted(third)){\n  if(a===b||a===c||b===c)continue;\n  const key=a+'-'+b+'-'+c;\n  if(!unique.has(key)){unique.add(key);tickets.push(key);}\n }\n return tickets;\n}\nfunction validDate(x){\n if(typeof x!=='string'||!/^\\d{4}-\\d{2}-\\d{2}$/.test(x))return false;\n const n=new Date(x+'T12:00:00Z');\n return Number.isFinite(n.valueOf())&&n.toISOString().slice(0,10)===x;\n}\nfunction validNums(a){return Array.isArray(a)&&a.length<=18&&\n a.every(x=>Number.isInteger(x)&&x>=1&&x<=18)&&new Set(a).size===a.length;}\nfunction validRecord(r){\n return r&&typeof r==='object'&&validDate(r.date)&&TRACKS.includes(r.track)&&\n Number.isInteger(r.race)&&r.race>=1&&r.race<=12&&\n validNums(r.first)&&validNums(r.second)&&validNums(r.third)&&\n typeof r.savedAt==='string'&&r.savedAt.length<=32&&\n ticketsFor(r.first,r.second,r.third).length>=1&&\n ticketsFor(r.first,r.second,r.third).length<=LIMIT;\n}\nlet records=[];\ntry{\n const raw=JSON.parse(localStorage.getItem(KEY)||'[]');\n if(Array.isArray(raw))records=raw.slice(-MAX_SAVED).filter(validRecord).map(r=>({\n  date:r.date,track:r.track,race:r.race,first:r.first,second:r.second,\n  third:r.third,savedAt:r.savedAt\n }));\n}catch(_){}\nlet first=new Set(),second=new Set(),third=new Set();\nconst groups=[['mFirst',()=>first],['mSecond',()=>second],['mThird',()=>third]];\nfunction keyOf(date,track,race){return date+'|'+track+'|'+race;}\nfunction currentKey(){return keyOf($('mDate').value,$('mTrack').value,Number($('mRace').value));}\nfunction toYen(x){return x.toLocaleString('ja-JP')+'円';}\nfunction message(x){$('mMsg').textContent=x;}\nfunction readForm(){\n const date=$('mDate').value,track=$('mTrack').value,race=Number($('mRace').value);\n if(!validDate(date)||!TRACKS.includes(track)||!Number.isInteger(race)||race<1||race>12)\n  return null;\n return {date,track,race};\n}\nconst MANUAL_ROSTER_KEY='keiba-nine-owner-manual-numbers-v1';\nconst PROVISIONAL_MAIL_KEY='keiba-nine-jrdb-personal-mail-v1';\nlet currentManualNames=new Map();\nfunction renderManualRoster(){\n const host=$('mRosterRows'),status=$('mRosterStatus');\n currentManualNames=new Map();\n host.replaceChildren();\n const choice=readForm();\n if(!choice){status.textContent='日付・競馬場・レースを先に選んでください。';return;}\n let maps,mails;\n try{\n  maps=JSON.parse(localStorage.getItem(MANUAL_ROSTER_KEY)||'[]');\n  mails=JSON.parse(localStorage.getItem(PROVISIONAL_MAIL_KEY)||'[]');\n }catch(_){status.textContent='馬番メモを読み取れませんでした。照合画面で確認してください。';return;}\n if(!Array.isArray(maps)||!Array.isArray(mails)){\n  status.textContent='保存されたメモの形式が正しくありません。';return;\n }\n const saved=maps.find(x=>x&&x.date===choice.date&&x.track===choice.track&&x.race===choice.race);\n if(!saved){\n  status.textContent='このレースの馬番・馬名メモは未登録です。JRDBの照合画面から本人が保存できます。';return;\n }\n const meeting=mails.find(x=>x&&x.kind==='jrdb-provisional'&&x.date===choice.date&&x.track===choice.track);\n const r=meeting&&Array.isArray(meeting.races)?meeting.races.find(x=>x&&x.race===choice.race):null;\n if(!r||!Array.isArray(r.horses)||saved.sourceMark!==JSON.stringify([r.postTime,r.expected,r.horses])){\n  status.textContent='想定メールが更新されたか元データがありません。古い馬番メモは表示しません。再照合してください。';return;\n }\n if(!Array.isArray(saved.rows)||!saved.rows.length||saved.rows.length>18){\n  status.textContent='馬番メモの形式が不正です。再照合してください。';return;\n }\n const numbers=new Set(),names=new Set();\n for(const item of saved.rows){\n  if(!item||!Number.isInteger(item.number)||item.number<1||item.number>18||\n     typeof item.name!=='string'||!item.name||item.name.length>35||\n     numbers.has(item.number)||names.has(item.name)){\n   host.replaceChildren();\n   status.textContent='馬番メモに重複・不正なデータがあります。再照合してください。';return;\n  }\n  numbers.add(item.number);names.add(item.name);\n }\n currentManualNames=new Map(saved.rows.map(x=>[x.number,x.name]));\n status.textContent='本人が手入力した馬番メモ：'+saved.rows.length+'頭（JRA公式による自動照合ではありません）';\n for(const item of saved.rows.slice().sort((a,b)=>a.number-b.number)){\n  const row=document.createElement('p');\n  row.className='roster-row';\n  row.textContent=item.number+'番 '+item.name;\n  host.append(row);\n }\n}\n\nfunction renderSelectedNames(){\n for(const [groupId,getSet,labelId] of [\n  ['mFirst',()=>first,'mFirstNames'],\n  ['mSecond',()=>second,'mSecondNames'],\n  ['mThird',()=>third,'mThirdNames']\n ]){\n  const selected=sorted(getSet());\n  $(labelId).textContent=selected.length?\n   '選択中：'+selected.map(n=>n+'番'+(currentManualNames.has(n)?' '+currentManualNames.get(n):'')).join(' ／ '):'';\n }\n}\n\nfunction readLocalCoverage(choice){\n const pending=new Map(),matched=new Set();\n let mail=[],notes=[];\n try{\n  mail=JSON.parse(localStorage.getItem(PROVISIONAL_MAIL_KEY)||'[]');\n  notes=JSON.parse(localStorage.getItem(MANUAL_ROSTER_KEY)||'[]');\n }catch(_){return {pending,matched};}\n if(!Array.isArray(mail)||!Array.isArray(notes))return {pending,matched};\n const meeting=mail.slice(0,48).find(x=>x&&x.kind==='jrdb-provisional'&&x.date===choice.date&&x.track===choice.track);\n if(!meeting||!Array.isArray(meeting.races)||meeting.races.length>12)return {pending,matched};\n for(const r of meeting.races){\n  if(!r||!Number.isInteger(r.race)||r.race<1||r.race>12||\n     !Number.isInteger(r.expected)||r.expected<1||r.expected>18||\n     !Array.isArray(r.horses)||r.horses.length!==r.expected||\n     r.horses.some(n=>typeof n!=='string'||!n||n.length>35)||\n     new Set(r.horses).size!==r.expected||pending.has(r.race))continue;\n  pending.set(r.race,r);\n  const typed=notes.slice(0,576).find(x=>x&&x.date===choice.date&&x.track===choice.track&&x.race===r.race);\n  if(!typed||typed.sourceMark!==JSON.stringify([r.postTime,r.expected,r.horses])||\n     !Array.isArray(typed.rows)||typed.rows.length!==r.expected)continue;\n  const names=new Set(),numbers=new Set(),source=new Set(r.horses);\n  let good=true;\n  for(const item of typed.rows){\n   if(!item||!Number.isInteger(item.number)||item.number<1||item.number>18||\n      typeof item.name!=='string'||!source.has(item.name)||\n      names.has(item.name)||numbers.has(item.number)){good=false;break;}\n   names.add(item.name);numbers.add(item.number);\n  }\n  if(good&&names.size===r.expected)matched.add(r.race);\n }\n return {pending,matched};\n}\nfunction renderDayReadiness(){\n const host=$('mDayCoverage'),status=$('mDayCoverageSummary'),date=$('mDate').value;\n host.replaceChildren();\n if(!validDate(date)){status.textContent='日付を選んでください。';return;}\n const tracks=new Set(records.filter(r=>r.date===date).map(r=>r.track));\n try{\n  const mails=JSON.parse(localStorage.getItem(PROVISIONAL_MAIL_KEY)||'[]');\n  if(Array.isArray(mails)){\n   for(const item of mails.slice(-48)){\n    if(item&&item.kind==='jrdb-provisional'&&item.date===date&&\n       TRACKS.includes(item.track)&&Array.isArray(item.races)&&item.races.length>0)\n      tracks.add(item.track);\n   }\n  }\n }catch(_){/* Corrupt local mail does not change saved drafts. */}\n if(!tracks.size){\n  status.textContent=date+'：この端末には該当日の想定メール・3連単下書きがまだありません。';\n  return;\n }\n let totalProvisional=0,totalManual=0,totalDraft=0,totalPoints=0;\n for(const track of [...tracks].sort((a,b)=>TRACKS.indexOf(a)-TRACKS.indexOf(b))){\n  const coverage=readLocalCoverage({date,track,race:1});\n  const saved=records.filter(r=>r.date===date&&r.track===track);\n  const count=saved.reduce((n,r)=>n+ticketsFor(r.first,r.second,r.third).length,0);\n  totalProvisional+=coverage.pending.size;\n  totalManual+=coverage.matched.size;\n  totalDraft+=saved.length;totalPoints+=count;\n  const button=document.createElement('button');button.type='button';\n  button.className='day-coverage-track'+($('mTrack').value===track?' active-track':'');\n  button.setAttribute('aria-label',track+'のレースを選択');\n  const heading=document.createElement('strong');heading.textContent=track;\n  const detail=document.createElement('small');\n  detail.textContent='想定'+coverage.pending.size+'R／馬名メモ'+coverage.matched.size+\n   'R／下書き'+saved.length+'R（'+count+'点）';\n  button.append(heading,detail);\n  button.onclick=()=>{\n   if($('mTrack').value===track)return;\n   if(hasUnsavedSelection()&&!confirm('編集中の買い目が未保存です。競馬場を切り替えて入力を破棄しますか？')){\n    message('競馬場の切替をやめました。先に下書きを保存してな。');return;\n   }\n   $('mTrack').value=track;$('mRace').value='1';loadSelected();\n   const picker=$('mRaceBoard');\n   if(typeof picker.scrollIntoView==='function')picker.scrollIntoView({behavior:'smooth',block:'start'});\n  };\n  host.append(button);\n }\n status.textContent=date+'：端末内'+tracks.size+'場／想定メール'+totalProvisional+\n  'R／馬名一致メモ'+totalManual+'R／下書き'+totalDraft+'R・'+totalPoints+\n  '点（100円換算 '+toYen(totalPoints*100)+'、未購入）。';\n}\nfunction renderNumberReview(){\n const status=$('mNumberReview');\n const used=sorted(new Set([...first,...second,...third]));\n if(!used.length){status.textContent='';status.className='number-review';return;}\n if(!currentManualNames.size){\n  status.className='number-review needs-check';\n  status.textContent='馬番メモが未登録または更新されているため、選択した馬番の対応関係を確認できません。JRA公式出馬表で馬名・馬番・取消を照合してください。';\n  return;\n }\n const unknown=used.filter(n=>!currentManualNames.has(n));\n status.className='number-review'+(unknown.length?' needs-check':'');\n status.textContent=unknown.length?\n  '注意：'+unknown.map(n=>n+'番').join('・')+'は本人転記の馬番メモに未登録です。取消や除外を意味しません。JRA公式出馬表で確認してください。':\n  '選択した馬番は本人転記の馬番メモにあります（JRA公式の自動照合や出走確定ではありません）。';\n}\nfunction renderRaceBoard(){\n const board=$('mRaceBoard'),status=$('mRaceBoardStatus'),choice=readForm();\n board.replaceChildren();\n if(!choice){\n  status.textContent='日付・競馬場を先に選んでください。';\n  return;\n }\n const saved=records.filter(r=>r.date===choice.date&&r.track===choice.track);\n const counts=new Map(saved.map(r=>[r.race,ticketsFor(r.first,r.second,r.third).length]));\n const coverage=readLocalCoverage(choice);\n status.textContent=choice.date+' '+choice.track+'：保存済み'+counts.size+'R／未入力'+(12-counts.size)+\n  'R。JRDB想定メール '+coverage.pending.size+'R／本人の馬名一致メモ '+coverage.matched.size+\n  'R（どちらも公式確認済みではありません）';\n for(let n=1;n<=12;n++){\n  const has=counts.has(n),provisional=coverage.pending.has(n),checked=coverage.matched.has(n),b=document.createElement('button');\n  b.type='button';\n  b.className='race-board-cell'+(has?' has-draft':'')+(provisional?' has-provisional':'')+\n   (checked?' has-manual':'')+(choice.race===n?' active-race':'');\n  b.setAttribute('aria-pressed',String(choice.race===n));\n  const name=document.createElement('span');name.textContent=n+'R';\n  const sub=document.createElement('small');sub.textContent=has?counts.get(n)+'点保存':'未入力';\n  const source=document.createElement('small');\n  source.textContent=checked?'馬名一致メモ':(provisional?'想定メールあり':'出走資料未取込');\n  b.append(name,sub,source);\n  b.onclick=()=>{\n   if(choice.race===n||!confirmLeavingSelection())return;\n   $('mRace').value=String(n);\n   loadSelected();\n   const panel=$('mFirst');\n   if(typeof panel.scrollIntoView==='function')panel.scrollIntoView({behavior:'smooth',block:'start'});\n  };\n  board.append(b);\n }\n}\nfunction render(){\n renderRaceBoard();\n renderManualRoster();\n renderSelectedNames();\n renderNumberReview();\n const combos=ticketsFor(first,second,third),points=combos.length;\n $('mCount').textContent=points+'点';\n $('mCost').textContent=toYen(points*100);\n $('mSave').disabled=!readForm()||points<1||points>LIMIT;\n const list=$('mTickets');list.replaceChildren();\n if(points<=LIMIT){for(const ticket of combos){\n  const li=document.createElement('li');li.textContent=ticket;list.append(li);\n }}\n for(const [id,getSet] of groups){const active=getSet();\n  for(const node of $(id).children){\n   const selected=active.has(Number(node.dataset.number));\n   node.className=selected?'num selected':'num';\n   node.setAttribute('aria-pressed',String(selected));\n  }\n }\n const race=Number($('mRace').value);\n $('mPrevRace').disabled=race<=1;\n $('mNextRace').disabled=race>=12;\n if(points>LIMIT)message(points+'点は48点を超えています。候補を減らしてください。');\n else if(points===0)message('各着順の馬番を選択してください。');\n else message(points+'点・'+toYen(points*100)+'。買い目は未購入の下書きです。');\n}\nfunction applyQuick(mode){\n let newFirst=new Set(first),newSecond=new Set(second),newThird=new Set(third),label='';\n if(mode==='single'){\n  if(first.size!==1){message('1着候補を1頭だけ選んでください。');return;}\n  const opponents=new Set([...second].filter(n=>!first.has(n)));\n  if(opponents.size<2){message('2着候補に相手を2頭以上選んでください。');return;}\n  newSecond=opponents;newThird=new Set(opponents);\n  label='1頭軸ながし';\n }else if(mode==='pair'){\n  if(first.size!==2){message('1着候補に軸の2頭を選んでください。');return;}\n  const opponents=new Set([...third].filter(n=>!first.has(n)));\n  if(!opponents.size){message('3着候補に軸以外の相手を選んでください。');return;}\n  newSecond=new Set(first);newThird=opponents;\n  label='2頭軸ながし（1・2着を入替）';\n }else if(mode==='copy'){\n  if(!second.size){message('先に2着候補を選んでください。');return;}\n  newThird=new Set(second);\n  label='2着候補を3着へコピー';\n }else return;\n const count=ticketsFor(newFirst,newSecond,newThird).length;\n if(!count||count>LIMIT){\n  message(count?count+'点は48点を超えるため反映しません。相手候補を減らしてください。':'有効な買い目がありません。軸と相手は違う馬番を選んでください。');\n  return;\n }\n first=newFirst;second=newSecond;third=newThird;\n render();\n message(label+'を反映：'+count+'点・'+toYen(count*100)+'。保存前に買い目を確認してください。');\n}\nfunction parseFormationText(raw){\n if(typeof raw!=='string'||raw.length<1||raw.length>1200)\n  throw Error('1着・2着・3着の3行を貼り付けてください。');\n const circles='①②③④⑤⑥⑦⑧⑨⑩⑪⑫⑬⑭⑮⑯⑰⑱';\n const text=raw.replace(/[①-⑱]/g,ch=>' '+(circles.indexOf(ch)+1)+' ').normalize('NFKC');\n const lines=text.split(/\\r?\\n/).map(x=>x.trim()).filter(Boolean);\n if(lines.length!==3)throw Error('1着・2着・3着を各1行、合計3行にしてください。');\n const positions=new Map();\n for(const line of lines){\n  const match=/^([123])\\s*着(?:候補)?\\s*:\\s*(.+)$/.exec(line);\n  if(!match)throw Error('「1着：①②」の形式で3行貼ってください。');\n  const key=Number(match[1]),list=match[2].trim();\n  if(positions.has(key))throw Error('同じ着順の行が重複しています。');\n  if(!/^[0-9\\s,、・/／]+$/.test(list))\n   throw Error('馬番以外の文字が含まれています。');\n  const parts=list.split(/[\\s,、・/／]+/).filter(Boolean);\n  if(parts.length<1||parts.length>18||parts.some(x=>!/^(?:[1-9]|1[0-8])$/.test(x)))\n   throw Error('各着順は1〜18番を区切って入力してください。');\n  const numbers=parts.map(Number);\n  if(!validNums(numbers))throw Error('同じ着順に馬番が重複しています。');\n  positions.set(key,new Set(numbers));\n }\n if(positions.size!==3)throw Error('1着・2着・3着を1回ずつ指定してください。');\n const count=ticketsFor(positions.get(1),positions.get(2),positions.get(3)).length;\n if(!count||count>LIMIT)\n  throw Error(count?count+'点は48点を超えています。馬番を減らしてください。':'3連単の有効な組み合わせがありません。');\n return {first:positions.get(1),second:positions.get(2),\n         third:positions.get(3),count};\n}\n\nfunction parseRankNumbers(raw,label){\n if(typeof raw!=='string'||raw.length>80)throw Error(label+'は80文字以内にしてな。');\n const circles='①②③④⑤⑥⑦⑧⑨⑩⑪⑫⑬⑭⑮⑯⑰⑱';\n const cleaned=raw.replace(/[①-⑱]/g,x=>' '+(circles.indexOf(x)+1)+' ').normalize('NFKC').trim();\n if(!cleaned)return [];\n if(!/^[0-9\\s,、・/／]+$/.test(cleaned))\n  throw Error(label+'には馬番だけを入力してな。');\n const items=cleaned.split(/[\\s,、・/／]+/).filter(Boolean);\n if(items.length>18||items.some(x=>!/^(?:[1-9]|1[0-8])$/.test(x)))\n  throw Error(label+'の馬番は1〜18を区切って入力してな。');\n const nums=items.map(Number);\n if(!validNums(nums))throw Error(label+'内に同じ馬番があります。');\n return nums;\n}\nfunction buildManualRankFormation(){\n const s=parseRankNumbers($('mRankS').value,'S');\n const a=parseRankNumbers($('mRankA').value,'A');\n const b=parseRankNumbers($('mRankB').value,'B');\n if(s.length<1||s.length>2||a.length<1)\n  throw Error('Sは1〜2頭、Aは1頭以上入力してください。');\n const joined=[...s,...a,...b];\n if(joined.length>18||new Set(joined).size!==joined.length)\n  throw Error('S・A・Bを通して馬番は重複できません。全体18頭以内にしてな。');\n if(joined.length<3)throw Error('3連単には異なる馬を3頭以上入力してください。');\n const fst=new Set(s);let best=null;\n for(let ac=1;ac<=a.length;ac++)for(let bc=0;bc<=b.length;bc++){\n  const second=new Set([...s,...a.slice(0,ac)]);\n  const third=new Set([...s,...a.slice(0,ac),...b.slice(0,bc)]);\n  const count=ticketsFor(fst,second,third).length;\n  if(!count||count>LIMIT)continue;\n  const inRange=count>=30&&count<=40;\n  const under=count<=40;\n  const rank=inRange?0:under?1:2;\n  const distance=inRange?Math.abs(count-36):under?40-count:count-40;\n  const score=rank*10000+distance*100+(a.length-ac)*3+(b.length-bc);\n  if(!best||score<best.score)\n   best={first:fst,second,third,count,score};\n }\n if(!best)throw Error('48点以内の有効なフォーメーションを作れません。候補を見直してな。');\n return best;\n}\n$('mRankBuild').onclick=()=>{\n try{\n  if(!readForm())throw Error('先に日付・競馬場・Rを選択してください。');\n  const planned=buildManualRankFormation();\n  if((first.size||second.size||third.size)&&\n     !confirm('現在選択中の買い目を'+planned.count+'点の手入力ランク編成に入れ替えますか？\\n下書き保存・購入はしません。'))return;\n  first=new Set(planned.first);\n  second=new Set(planned.second);\n  third=new Set(planned.third);\n  render();\n  const hint=planned.count>=30&&planned.count<=40?'30〜40点の目安内':'条件上、30〜40点には届かないか超過するため'+planned.count+'点';\n  $('mRankStatus').textContent='手入力ランクから'+planned.count+'点を組み立てました（'+hint+'）。馬番・出走取消・JRA公式出馬表は未照合です。';\n  message('本人入力ランクの編成 '+planned.count+'点・'+toYen(planned.count*100)+'。下書き保存・購入はまだです。');\n }catch(e){\n  $('mRankStatus').textContent='編成できません：'+(e instanceof Error?e.message:'馬番を確認してな。');\n }\n};\nfunction changeRace(delta){\n const next=Number($('mRace').value)+delta;\n if(next<1||next>12||!confirmLeavingSelection())return;\n $('mRace').value=String(next);\n loadSelected();showDay();\n}\nfunction showDay(){\n renderDayReadiness();\n renderRaceBoard();\n const host=$('mSaved');host.replaceChildren();\n const date=$('mDate').value;\n const rows=records.filter(r=>r.date===date).slice().sort((a,b)=>a.track.localeCompare(b.track,'ja')||a.race-b.race);\n const pointTotal=rows.reduce((sum,r)=>sum+ticketsFor(r.first,r.second,r.third).length,0);\n $('mDaySummary').textContent='この日の未購入下書き：'+rows.length+'R／'+pointTotal+'点／'+toYen(pointTotal*100)+'（全部100円換算・購入額ではありません）';\n if(!rows.length){const p=document.createElement('p');p.className='muted';p.textContent='この日付に保存した下書きはありません。';host.append(p);return;}\n for(const r of rows){\n  const div=document.createElement('div');div.className='saved';\n  const title=document.createElement('strong');title.textContent=r.track+r.race+'R｜'+ticketsFor(r.first,r.second,r.third).length+'点';\n  const note=document.createElement('p');note.className='muted';\n  note.textContent='1着 '+r.first.join('・')+'／2着 '+r.second.join('・')+'／3着 '+r.third.join('・')+'｜未購入の下書き';\n  const edit=document.createElement('button');edit.className='secondary';edit.textContent='編集';\n  edit.onclick=()=>{\n   const same=$('mTrack').value===r.track&&Number($('mRace').value)===r.race;\n   if(!same&&!confirmLeavingSelection())return;\n   $('mTrack').value=r.track;$('mRace').value=String(r.race);loadSelected();\n   message(r.track+r.race+'Rの下書きを表示したで。上のフォームで確認・修正して、保存ボタンを押してな。');\n   const panel=$('mFirst');\n   if(typeof panel.scrollIntoView==='function')panel.scrollIntoView({behavior:'smooth',block:'start'});\n  };\n  const del=document.createElement('button');del.className='secondary';del.textContent='削除';\n  del.onclick=()=>{\n   if(!confirm(r.track+r.race+'Rの下書きを削除しますか？'))return;\n   const old=records.slice();records=records.filter(x=>keyOf(x.date,x.track,x.race)!==keyOf(r.date,r.track,r.race));\n   if(!persist()){records=old;message('削除を保存できませんでした。');return;}\n   if(currentKey()===keyOf(r.date,r.track,r.race))loadSelected();\n   showDay();message('下書きを削除しました。');\n  };\n  div.append(title,note,edit,del);host.append(div);\n }\n}\nlet displayedChoice=null;\nfunction loadSelected(){\n const choice=readForm();\n const r=choice&&records.find(x=>keyOf(x.date,x.track,x.race)===\n  keyOf(choice.date,choice.track,choice.race));\n first=new Set(r?r.first:[]);second=new Set(r?r.second:[]);third=new Set(r?r.third:[]);\n displayedChoice=choice?{...choice}:null;\n render();\n renderDayReadiness();\n}\nfunction confirmLeavingSelection(){\n if(!hasUnsavedSelection())return true;\n if(confirm('編集中の3連単は未保存です。別のレースに移ると入力が消えます。続けますか？'))return true;\n message('切り替えをやめました。今の3連単を保存してから移動してな。');\n return false;\n}\nfunction restoreDisplayedChoice(){\n if(!displayedChoice)return;\n $('mDate').value=displayedChoice.date;\n $('mTrack').value=displayedChoice.track;\n $('mRace').value=String(displayedChoice.race);\n}\nfunction persist(){\n try{localStorage.setItem(KEY,JSON.stringify(records));return true;}\n catch(_){return false;}\n}\nfor(const [id,getSet] of groups){\n const host=$(id);\n for(let n=1;n<=18;n++){\n  const btn=document.createElement('button');btn.type='button';btn.className='num';\n  btn.textContent=String(n);btn.dataset.number=String(n);\n  btn.setAttribute('aria-pressed','false');\n  btn.onclick=()=>{const set=getSet();if(set.has(n))set.delete(n);else set.add(n);render();};\n  host.append(btn);\n }\n}\n$('mApplyPaste').onclick=()=>{\n const choice=readForm();\n if(!choice){message('先に日付・競馬場・レースを選択してな。');return;}\n try{\n  const parsed=parseFormationText($('mPaste').value);\n  if((first.size||second.size||third.size)&&\n     !confirm('現在選択中の馬番を、貼り付けた'+parsed.count+'点に入れ替えますか？\\n保存済みの下書きは上書きしません。'))\n   return;\n  first=parsed.first;second=parsed.second;third=parsed.third;\n  render();\n  message('貼り付けた3連単 '+parsed.count+'点・'+toYen(parsed.count*100)+\n   'を反映したで。まだ保存・購入はしていません。組み合わせを確認してな。');\n }catch(err){message('反映できません：'+(err instanceof Error?err.message:'形式を確認してください。'));}\n};\n$('mAxisSingle').onclick=()=>applyQuick('single');\n$('mAxisPair').onclick=()=>applyQuick('pair');\n$('mCopyThird').onclick=()=>applyQuick('copy');\n$('mPrevRace').onclick=()=>changeRace(-1);\n$('mNextRace').onclick=()=>changeRace(1);\n\nfunction nextWeekendDate(targetDay){\n const today=new Date(Date.now()+9*60*60*1000);\n const delta=(targetDay-today.getUTCDay()+7)%7;\n return new Date(Date.UTC(today.getUTCFullYear(),today.getUTCMonth(),\n  today.getUTCDate()+delta)).toISOString().slice(0,10);\n}\nfunction hasUnsavedSelection(){\n const old=displayedChoice&&records.find(x=>keyOf(x.date,x.track,x.race)===\n  keyOf(displayedChoice.date,displayedChoice.track,displayedChoice.race));\n const identical=(current,saved)=>sorted(current).join(',')===sorted(saved||[]).join(',');\n return !identical(first,old&&old.first)||!identical(second,old&&old.second)||\n  !identical(third,old&&old.third);\n}\nfunction jumpWeekend(targetDay){\n const date=nextWeekendDate(targetDay);\n if($('mDate').value===date)return;\n if(hasUnsavedSelection()&&!confirm('編集中の馬番が保存されていません。日付を切り替えるとこの入力は消えます。続けますか？')){\n  message('日付を変えずに保持しました。まず3連単の下書きを保存してな。');\n  return;\n }\n $('mDate').value=date;\n loadSelected();showDay();\n}\n$('mSaturday').onclick=()=>jumpWeekend(6);\n$('mSunday').onclick=()=>jumpWeekend(0);\n$('mDate').value=new Date(Date.now()+9*60*60*1000).toISOString().slice(0,10);\n$('mDate').onchange=()=>{\n if(!confirmLeavingSelection()){restoreDisplayedChoice();return;}\n loadSelected();showDay();\n};\n$('mImport').onchange=async()=>{\n const picker=$('mImport'),file=picker.files&&picker.files[0];\n if(!file)return;\n try{\n  if(!Number.isSafeInteger(file.size)||file.size<1||file.size>1024*1024)\n   throw new Error('ファイルサイズが不正です（上限1MB）。');\n  const data=JSON.parse(await file.text()),raw=data&&data.records;\n  if(!data||data.format!=='keiba-nine-owner-drafts-1'||\n     !Array.isArray(raw)||raw.length<1||raw.length>MAX_SAVED||\n     !raw.every(validRecord))\n   throw new Error('下書きのバックアップ形式か内容が正しくありません。');\n  const keys=new Set(raw.map(r=>keyOf(r.date,r.track,r.race)));\n  if(keys.size!==raw.length)\n   throw new Error('同じ日付・レースが重複しているため復元できません。');\n  const restored=raw.map(r=>({date:r.date,track:r.track,race:r.race,\n   first:r.first.slice(),second:r.second.slice(),third:r.third.slice(),savedAt:r.savedAt}));\n  if(!confirm('現在の下書き '+records.length+'件を、バックアップ '+restored.length+\n    '件で全件置き換えます。事前に現在のJSONを保存しましたか？'))return;\n  const previous=records;\n  records=restored;\n  if(!persist()){\n   records=previous;message('端末へ保存できず、元の下書きはそのままです。');return;\n  }\n  loadSelected();showDay();\n  message('下書き '+restored.length+'件を復元しました。これは購入記録ではありません。');\n }catch(err){message('復元できません：'+(err instanceof Error?err.message:'ファイルを確認してください。'));}\n finally{picker.value='';}\n};\nfunction handleRaceSelectorChange(){\n if(!confirmLeavingSelection()){restoreDisplayedChoice();return;}\n loadSelected();showDay();\n}\n$('mTrack').onchange=handleRaceSelectorChange;\n$('mRace').onchange=handleRaceSelectorChange;\n$('mReset').onclick=()=>{first.clear();second.clear();third.clear();render();};\n$('mSave').onclick=()=>{\n const choice=readForm(),combos=ticketsFor(first,second,third);\n if(!choice||combos.length<1||combos.length>LIMIT){message('日付・競馬場・点数を確認してください。');return;}\n const i=records.findIndex(x=>keyOf(x.date,x.track,x.race)===currentKey());\n if(i>=0&&!confirm('このレースの下書きを上書きしますか？'))return;\n if(i<0&&records.length>=MAX_SAVED){message('保存上限です。古い下書きを削除してください。');return;}\n const old=records.slice(),r={...choice,first:sorted(first),second:sorted(second),third:sorted(third),\n  savedAt:new Date().toISOString()};\n if(i>=0)records[i]=r;else records.push(r);\n if(!persist()){records=old;message('保存できません。Safariのストレージを確認してください。');return;}\n showDay();message('下書きを保存しました。端末内保存のみ・購入記録ではありません。');\n};\n$('mExport').onclick=()=>{\n if(!records.length){message('保存された下書きがありません。');return;}\n try{\n  const data={format:'keiba-nine-owner-drafts-1',exportedAt:new Date().toISOString(),records};\n  const blob=new Blob([JSON.stringify(data,null,2)],{type:'application/json'});\n  const url=URL.createObjectURL(blob),a=document.createElement('a');\n  a.href=url;a.download='keiba-nine-manual-drafts.json';a.click();\n  URL.revokeObjectURL(url);message('バックアップを書き出しました。ファイルの保存先を確認してください。');\n }catch(_){message('このブラウザでは書き出せません。Safariでお試しください。');}\n};\n\nlet pendingBulk=null;\nfunction clearBulkPreview(){\n pendingBulk=null;\n $('mBulkApply').disabled=true;\n $('mBulkPreview').replaceChildren();\n}\nfunction parseBulkForecast(raw){\n if(typeof raw!=='string'||!raw.trim()||raw.length>25000)\n  throw Error('1〜36レースの4行セットを入力してください。');\n const lines=raw.replace(/\\r/g,'').split('\\n').map(x=>x.trim()).filter(Boolean);\n if(lines.length<4||lines.length%4!==0||lines.length/4>36)\n  throw Error('「日付 競馬場R」と1着・2着・3着を4行1セットで、最大36Rまで入力してください。');\n const drafts=[],used=new Set();\n const header=/^(\\d{4}-\\d{2}-\\d{2})\\s+(札幌|函館|福島|新潟|東京|中山|中京|京都|阪神|小倉)\\s*(1[0-2]|[1-9])\\s*R$/;\n for(let i=0;i<lines.length;i+=4){\n  const matched=header.exec(lines[i].normalize('NFKC'));\n  if(!matched||!validDate(matched[1]))\n   throw Error((i/4+1)+'件目：日付・競馬場・Rの見出しを確認してください。');\n  const date=matched[1],track=matched[2],race=Number(matched[3]);\n  const raceKey=keyOf(date,track,race);\n  if(used.has(raceKey))\n   throw Error((i/4+1)+'件目：同じレースが重複しています。');\n  used.add(raceKey);\n  let formed;\n  try{formed=parseFormationText(lines.slice(i+1,i+4).join('\\n'));}\n  catch(e){throw Error(track+race+'R：'+(e instanceof Error?e.message:'買い目を確認してください。'));}\n  drafts.push({date,track,race,first:sorted(formed.first),second:sorted(formed.second),\n    third:sorted(formed.third),savedAt:new Date().toISOString(),points:formed.count});\n }\n return drafts;\n}\n$('mBulkPaste').oninput=()=>{\n clearBulkPreview();\n $('mBulkStatus').textContent='入力が変わったため前の検査結果を破棄しました。もう一度検査してください。';\n};\n$('mBulkReview').onclick=()=>{\n clearBulkPreview();\n try{\n  const raw=$('mBulkPaste').value,drafts=parseBulkForecast(raw);\n  const existing=new Set(records.map(r=>keyOf(r.date,r.track,r.race)));\n  const overwritten=drafts.filter(r=>existing.has(keyOf(r.date,r.track,r.race))).length;\n  const count=records.length+drafts.length-overwritten;\n  if(count>MAX_SAVED)throw Error('保存上限300レースを超えます。古い下書きを整理してください。');\n  const preview=$('mBulkPreview');\n  for(const r of drafts){\n   const details=document.createElement('details');details.className='bulk-review-card';\n   const summary=document.createElement('summary');\n   summary.textContent=r.date+' '+r.track+r.race+'R：'+r.points+'点／'+\n     toYen(r.points*100)+(existing.has(keyOf(r.date,r.track,r.race))?'（既存を上書き）':'（新規）');\n   const formation=document.createElement('p');\n   formation.textContent='1着 '+r.first.join('・')+'／2着 '+r.second.join('・')+\n     '／3着 '+r.third.join('・');\n   const ticketList=document.createElement('p');ticketList.className='bulk-review-tickets';\n   ticketList.textContent='実際の全買い目（重複なし）：'+ticketsFor(r.first,r.second,r.third).join(' ／ ');\n   details.append(summary,formation,ticketList);\n   preview.append(details);\n  }\n  pendingBulk={raw,drafts};\n  $('mBulkStatus').textContent=drafts.length+'R検査完了／上書き'+overwritten+'R。実購入・出走確定は未確認です。';\n  $('mBulkApply').disabled=false;\n }catch(e){$('mBulkStatus').textContent='一括検査できません：'+(e instanceof Error?e.message:'入力を確認してください。');}\n};\n$('mBulkApply').onclick=()=>{\n if(!pendingBulk||pendingBulk.raw!==$('mBulkPaste').value){\n  clearBulkPreview();\n  $('mBulkStatus').textContent='入力内容が変わっています。再検査してください。';return;\n }\n const incoming=pendingBulk.drafts,keys=new Set(incoming.map(r=>keyOf(r.date,r.track,r.race)));\n const overwritten=records.filter(r=>keys.has(keyOf(r.date,r.track,r.race))).length;\n const proposed=records.filter(r=>!keys.has(keyOf(r.date,r.track,r.race))).concat(\n  incoming.map(({points,...r})=>r));\n if(proposed.length>MAX_SAVED||!proposed.every(validRecord)){\n  clearBulkPreview();$('mBulkStatus').textContent='保存対象の再検査に失敗しました。';return;\n }\n if(!confirm(incoming.length+'レースの下書きを一括保存する？\\n既存'+overwritten+\n  'レースを上書きします。\\n現在編集途中のフォームも再読み込みします。\\n購入記録には追加しません。'))return;\n try{\n  localStorage.setItem(KEY,JSON.stringify(proposed));\n }catch(_){$('mBulkStatus').textContent='保存できませんでした。既存の下書きは変更していません。';return;}\n records=proposed;\n clearBulkPreview();\n $('mBulkPaste').value='';\n loadSelected();showDay();\n $('mBulkStatus').textContent=incoming.length+'レースの下書きを端末内に保存しました（未購入・公式未照合）。';\n};\n\nloadSelected();showDay();"
